for locale, values in history.items():
    path=root/'resources/js/localization/messages/events'/f'{locale}.ts'
    text=path.read_text(encoding='utf-8')
    if '    history: {' in text:
        continue
    lines=['    history: {']
    for key,value in values.items():
        lines.append(f'      {key}: {json.dumps(value, ensure_ascii=False)},')
    lines.append('    },')
    block='\n'.join(lines)+'\n'
    marker='  events: {\n'
    if marker not in text:
        raise SystemExit(f'Missing events marker in {path}')
    path.write_text(text.replace(marker, marker+block, 1), encoding='utf-8')
